   295	
   296	/**
   297	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   298	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   299	 * is whether the user with that login is typing/leaving on the report or not.
   300	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   301	 *
   302	 * This method makes sure that no matter which we get, we return the "new" format
   303	 */
   304	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   305	    let normalizedStatus: ReportUserIsTyping;
   306	
   307	    if (typingStatus.userLogin) {
   308	        normalizedStatus = {[typingStatus.userLogin]: true};
   309	    } else {
   310	        normalizedStatus = typingStatus;
   311	    }
   312	
   313	    return normalizedStatus;
   314	}
